arguments.query:
query PlayNexusContextTest {
  search(query: "Assassin's Creed Shadows", first: 5) {
    query
    games {
      id
      name
      slug
      status
      studio { id name slug }
      platforms { id name slug }
      productCount
      videoCount
    }
    studios {
      id
      name
      slug
      status
      gameCount
    }
    products {
      id
      title
      slug
      status
      visibility
      price
      game { id name slug }
      platforms { id name slug }
    }
    content {
      id
      type
      title
      slug
      status
      game { id name slug }
      relatedProduct { id title slug }
    }
  }
}
